// @ts-check
import fs from 'node:fs';
import path from 'node:path';

/**
 * Syncs `impact-map.auto.json` (or `impact-map.json`) from CodeMap v5 routes, APIs, and service chains,
 * preserving manual rules while keeping auto-generated SaaS mappings concise and controller-scoped.
 * @param {string} impactMapPath
 * @param {Record<string, any>} codeMap
 */
export function syncImpactMapFromCodeMap(impactMapPath, codeMap) {
  /** @type {{ description: string, rules: Array<Record<string, any>> }} */
  let current = {
    description:
      'Maps changed repository files to targeted Playwright spec files. Custom manual rules are preserved; autoGenerated rules sync from knowledge/code-map.json.',
    rules: [],
  };
  if (fs.existsSync(impactMapPath)) {
    try {
      const parsed = JSON.parse(fs.readFileSync(impactMapPath, 'utf8'));
      if (parsed && Array.isArray(parsed.rules)) current = parsed;
    } catch {
      // fall back cleanly
    }
  }

  /** @type {Map<string, Set<string>>} */
  const chainFilesByRoute = new Map();
  for (const ch of Array.isArray(codeMap.serviceChains) ? codeMap.serviceChains : []) {
    if (!ch?.route) continue;
    const set = chainFilesByRoute.get(ch.route) || new Set();
    for (const f of [
      ch.viewFile,
      ch.frontendApiFile,
      ch.controllerFile,
      ...(Array.isArray(ch.serviceFiles) ? ch.serviceFiles.slice(0, 6) : []),
      ...(Array.isArray(ch.mapperFiles) ? ch.mapperFiles.slice(0, 6) : []),
      ...(Array.isArray(ch.xmlFiles) ? ch.xmlFiles.slice(0, 6) : []),
    ]) {
      if (typeof f === 'string' && f && !f.includes(' ')) set.add(f);
    }
    chainFilesByRoute.set(ch.route, set);
  }

  const manualRules = current.rules.filter((r) => !r.autoGenerated);
  const autoRules = [];
  const seenKey = new Set();

  for (const r of Object.values(codeMap.routes || {})) {
    if (!r.coveringSpecs || r.coveringSpecs.length === 0) continue;
    const sources = [
      ...new Set([
        r.frontendFile,
        ...(r.linkedBackendFiles || []),
        ...(chainFilesByRoute.get(r.route) || []),
      ].filter(Boolean)),
    ].sort();
    if (sources.length === 0) continue;
    const specs = [...new Set(r.coveringSpecs)].sort();
    const key = `${sources.join(',')}->${specs.join(',')}`;
    if (seenKey.has(key)) continue;
    seenKey.add(key);
    autoRules.push({
      autoGenerated: true,
      route: r.route,
      match: sources,
      specs,
    });
  }

  const next = { ...current, rules: [...manualRules, ...autoRules] };
  fs.mkdirSync(path.dirname(impactMapPath), { recursive: true });
  fs.writeFileSync(impactMapPath, JSON.stringify(next, null, 2) + '\n', 'utf8');
  return { manualRulesCount: manualRules.length, autoRulesCount: autoRules.length };
}

/**
 * Renders Living Code Map v5 Markdown (`SYSTEM_MAP.md`) including graph engine metadata,
 * cross-service RPC/MQ/MyBatis telemetry, top full-stack service chains, and defect ledger.
 * @param {Record<string, any>} codeMap
 * @param {string} [lang]
 * @returns {string}
 */
export function generateLivingSystemMapMarkdown(codeMap, lang = 'zh') {
  const isZh = lang === 'zh';
  const routes = Object.values(codeMap.routes || {}).filter((r) => !r.stale);
  const defects = (codeMap.defects || []).filter((/** @type {any} */ d) => d.status === 'open' || d.status === 'resolved-candidate');
  const cov = codeMap.coverage || { totalRoutes: routes.length, coveredRoutes: 0, coveragePct: 0, uncoveredRoutes: [] };
  const ge = codeMap.meta?.graphEngine || null;
  const bridges = codeMap.crossServiceBridges || null;
  const apisCount = codeMap.apis && typeof codeMap.apis === 'object' ? Object.keys(codeMap.apis).length : 0;
  const chains = Array.isArray(codeMap.serviceChains) ? codeMap.serviceChains : [];

  const engineBadge = ge
    ? `${ge.provider || 'builtin'} (${ge.mode || 'builtin-fallback'}${ge.version ? ` v${ge.version}` : ''}, coverage=${ge.coverage?.clean ? 'clean' : `partial/fallback ratio=${ge.coverage?.unresolvedRatio ?? 1}`})`
    : 'builtin (builtin-fallback)';

  const lines = [
    isZh
      ? `# 活体系统与代码知识地图 (SYSTEM_MAP v${codeMap.version || '5.0'} · Revision v${codeMap.revision || 1})`
      : `# Living System & Code Knowledge Map (v${codeMap.version || '5.0'} · Revision v${codeMap.revision || 1})`,
    '',
    isZh
      ? `> 自动同步演进 (Schema v${codeMap.schemaVersion || 5}) · 引擎：\`${engineBadge}\` · 更新时间：\`${codeMap.updatedAt}\` · 目标：\`${codeMap.baseURL || '未绑定远端 URL'}\``
      : `> Auto-evolving Agent Memory (Schema v${codeMap.schemaVersion || 5}) · Engine: \`${engineBadge}\` · Updated: \`${codeMap.updatedAt}\` · Target: \`${codeMap.baseURL || 'local/unconfigured'}\``,
    ...(ge?.degradedReason
      ? [isZh ? `> 降级说明：\`${ge.degradedReason}\`` : `> Engine Degraded Reason: \`${ge.degradedReason}\``]
      : []),
    '',
    isZh ? '## 1. 系统演进与测试覆盖总览' : '## 1. System Evolution & Coverage Summary',
    isZh
      ? `- **当前地图修订号**：\`Revision #${codeMap.revision}\`（累计历史记录 \`${(codeMap.history || []).length}\` 次）`
      : `- **Knowledge Revision**: \`#${codeMap.revision}\` (${(codeMap.history || []).length} recorded revisions)`,
    isZh
      ? `- **路由与源码规模**：已测绘 \`${cov.totalRoutes}\` 条活跃路由 · 已覆盖 \`${cov.coveredRoutes}\` 条（覆盖率 **${cov.coveragePct}%**）· 扫描仓库源码 \`${codeMap.sourceSummary?.repoFilesScanned ?? 0}\` 个${codeMap.sourceSummary?.truncated ? ' *(已达扫描上限截断)*' : ''} · 规范 API \`${apisCount}\` 个 · 后端端点 \`${codeMap.sourceSummary?.backendEndpointsCount ?? 0}\` 个 · 数据表 \`${(codeMap.sourceSummary?.dbEntities || []).length}\` 张`
      : `- **Topology & Source Scale**: ${cov.totalRoutes} active routes (${cov.coveredRoutes} covered, **${cov.coveragePct}%**) · ${codeMap.sourceSummary?.repoFilesScanned ?? 0} repo files${codeMap.sourceSummary?.truncated ? ' *(TRUNCATED)*' : ''} · ${apisCount} normalized APIs · ${codeMap.sourceSummary?.backendEndpointsCount ?? 0} backend endpoints · ${(codeMap.sourceSummary?.dbEntities || []).length} DB entities`,
    ...(bridges
      ? [
          isZh
            ? `- **跨服务与数据桥接**：调用链 \`${chains.length}\` 条 · Feign 桥接 \`${bridges.feignLinkedCount ?? 0}/${bridges.feignCount ?? 0}\` · Dubbo 服务 \`${bridges.dubboCount ?? 0}\` · RocketMQ 边 \`${bridges.mqCount ?? 0}\` · XXL-Job \`${bridges.xxlJobCount ?? 0}\` · MyBatis XML 语句 \`${bridges.mybatisStatementsCount ?? 0}\``
            : `- **Cross-Service & Persistence Bridges**: ${chains.length} service chain(s) · Feign ${bridges.feignLinkedCount ?? 0}/${bridges.feignCount ?? 0} linked · Dubbo ${bridges.dubboCount ?? 0} · RocketMQ ${bridges.mqCount ?? 0} · XXL-Job ${bridges.xxlJobCount ?? 0} · MyBatis XML statements ${bridges.mybatisStatementsCount ?? 0}`,
        ]
      : []),
    ...(Array.isArray(codeMap.meta?.sourceRepos) && codeMap.meta.sourceRepos.length > 1
      ? [
          isZh
            ? `- **关联源码仓库 (${codeMap.meta.sourceRepos.length})**：${codeMap.meta.sourceRepos.map((/** @type {string} */ r) => `\`${r}\``).join(', ')}`
            : `- **Indexed Source Repos (${codeMap.meta.sourceRepos.length})**: ${codeMap.meta.sourceRepos.map((/** @type {string} */ r) => `\`${r}\``).join(', ')}`,
        ]
      : []),
    isZh
      ? `- **待治理隐患（Open / Candidate）**：\`${defects.length}\` 项`
      : `- **Active Defects (Open / Candidate)**: \`${defects.length}\``,
    '',
    isZh ? '## 2. 全链路路由 ↔ 源码 ↔ 接口 ↔ 用例映射表' : '## 2. Full-Link Route ↔ Code ↔ API ↔ Spec Matrix',
    isZh
      ? '| 路由 | 原型 | 前端源文件 | 关联 API / 后端 | 覆盖用例 | 最近状态 |'
      : '| Route | Archetype | Frontend File | Linked APIs / Backend | Covering Specs | Last Status |',
    '|---|---|---|---|---|---|',
  ];

  for (const r of routes.slice(0, 100)) {
    const apis = [...(r.linkedApis || []).slice(0, 3), ...(r.linkedBackendFiles || []).slice(0, 2)].join(', ') || '-';
    const specs = (r.coveringSpecs || []).join(', ') || (isZh ? '*(待补全)*' : '*(uncovered)*');
    lines.push(
      `| \`${r.route}\` | \`${r.archetype || 'unknown'}\` | \`${r.frontendFile || '-'}\` | ${apis.replace(/\|/g, '\\|')} | ${specs} | \`${r.lastResult || 'untested'}\` |`
    );
  }
  lines.push('');

  if (chains.length > 0) {
    lines.push(
      isZh ? '## 3. 全栈业务调用链摘要 (Top Service Chains)' : '## 3. Full-Stack Service Chains (Top Entries)',
      ''
    );
    for (const ch of chains.slice(0, 25)) {
      const parts = [
        ch.viewFile ? `Vue(\`${ch.viewFile}\`)` : `Route(\`${ch.route}\`)`,
        `API(\`${ch.apiMethod || 'ANY'} ${ch.apiPath}${ch.apiFnName ? `#${ch.apiFnName}` : ''}\`)`,
        ch.controllerFile ? `Ctrl(\`${ch.controllerFile}${ch.controllerMethod ? `#${ch.controllerMethod}` : ''}\`)` : '',
        ch.serviceFiles?.length ? `Svc(\`${ch.serviceFiles.slice(0, 2).join(', ')}\`)` : '',
        ch.feignFiles?.length ? `Feign(\`${ch.feignFiles.slice(0, 2).join(', ')}\`)` : '',
        ch.dbTables?.length ? `DB(\`${ch.dbTables.slice(0, 4).join(', ')}\`)` : '',
      ].filter(Boolean);
      lines.push(`- ${parts.join(' → ')}`);
    }
    lines.push('');
  }

  lines.push(isZh ? '## 4. 未覆盖优先探索目标 (Uncovered Queue)' : '## 4. Uncovered High-Priority Targets', '');
  if ((cov.uncoveredRoutes || []).length === 0) {
    lines.push(isZh ? '- 所有已测绘活跃路由均已有测试覆盖。' : '- All active mapped routes have spec coverage.', '');
  } else {
    for (const u of cov.uncoveredRoutes.slice(0, 25)) {
      lines.push(`- \`${u}\``);
    }
    lines.push('');
  }

  lines.push(isZh ? '## 5. 已知缺陷与接口瀑布冗余账本' : '## 5. Known Defects & Redundant Waterfall Ledger', '');
  if (defects.length === 0 && (codeMap.duplicateWaterfalls || []).length === 0) {
    lines.push(isZh ? '- 暂未发现断链路由、Console 报错或重复 API 瀑布。' : '- No broken route imports, console errors, or duplicate API waterfalls recorded.', '');
  } else {
    for (const d of defects.slice(0, 30)) {
      lines.push(`- **[${d.severity || 'P2'} · ${d.type} · ${d.status}]** \`${d.route}\` (seen ${d.seenCount}x): ${d.message}`);
    }
    for (const w of (codeMap.duplicateWaterfalls || []).slice(0, 15)) {
      lines.push(`- **[Waterfall]** \`${w.route}\`: \`${w.endpoint}\` fired ${w.count}x on single view load`);
    }
    lines.push('');
  }

  if ((codeMap.perfSnapshots || []).length > 0) {
    const latest = codeMap.perfSnapshots[codeMap.perfSnapshots.length - 1];
    lines.push(
      isZh ? '## 6. 最新性能与 SLO 基线' : '## 6. Latest Performance & SLO Baseline',
      `- Measured At: \`${latest.measuredAt}\` · Budget Passed: \`${latest.budgetPassed}\` · API P95: \`${latest.apiP95Ms ?? '-'} ms\` · LCP: \`${latest.browserSummary?.[0]?.lcpMs ?? '-'} ms\``,
      ''
    );
  }

  return lines.join('\n');
}
